using UnityEngine;

namespace BOW.Game
{
    public enum Sfx
    {
        Blast,
        PaddleHit,
        WallBounce,
        BallClack,
        Goal,
        Conceded,
        CountdownBeep,
        Go,
        Eliminated,
        Win,
        Lose,
        Click,
    }

    /// <summary>
    /// Plays sound effects (TDD 11.1). A small pool of 2D audio sources lives for the whole session; the effects
    /// volume comes from settings and the master volume from the AudioListener. Clips are generated by
    /// <see cref="SfxSynth"/> until real sound assets replace them.
    /// </summary>
    public static class GameAudio
    {
        private const int Voices = 10;
        private static AudioSource[] _sources;
        private static AudioClip[] _clips;
        private static float[] _lastPlayed;
        private static int _next;

        public static void Play(Sfx sfx, float volume = 1f, float pitch = 1f)
        {
            Ensure();
            int i = (int)sfx;
            // Rapid repeats of the same small sound (many wall bounces in one frame) would just be noise.
            if (Time.unscaledTime - _lastPlayed[i] < 0.03f && sfx != Sfx.CountdownBeep) return;
            _lastPlayed[i] = Time.unscaledTime;

            float effects = SettingsStore.Current.EffectsVolume / (float)GameSettings.MaxVolume;
            if (effects <= 0f) return;
            var source = _sources[_next];
            _next = (_next + 1) % _sources.Length;
            source.pitch = pitch;
            source.PlayOneShot(_clips[i], volume * effects);
        }

        private static void Ensure()
        {
            if (_sources != null && _sources[0] != null) return;
            var go = new GameObject("Game Audio");
            Object.DontDestroyOnLoad(go);
            _sources = new AudioSource[Voices];
            for (int i = 0; i < Voices; i++)
            {
                var s = go.AddComponent<AudioSource>();
                s.playOnAwake = false;
                s.spatialBlend = 0f;
                _sources[i] = s;
            }
            if (_clips == null)
            {
                _clips = new[]
                {
                    SfxSynth.Blast(), SfxSynth.PaddleHit(), SfxSynth.WallBounce(), SfxSynth.BallClack(),
                    SfxSynth.Goal(), SfxSynth.Conceded(), SfxSynth.CountdownBeep(), SfxSynth.Go(),
                    SfxSynth.Eliminated(), SfxSynth.Win(), SfxSynth.Lose(), SfxSynth.Click(),
                };
                _lastPlayed = new float[_clips.Length];
                for (int i = 0; i < _lastPlayed.Length; i++) _lastPlayed[i] = -1f;
            }
        }
    }

    /// <summary>
    /// Short vibration pulses (TDD 11.2): 20 ms on your blast, 40 ms when you concede. Uses Android's
    /// VibrationEffect where available; does nothing elsewhere or when Vibration is off in settings.
    /// </summary>
    public static class Haptics
    {
#if UNITY_ANDROID && !UNITY_EDITOR
        private static AndroidJavaObject _vibrator;
        private static bool _failed;
#endif

        public static void Pulse(int milliseconds)
        {
            if (!SettingsStore.Current.Haptics) return;
#if UNITY_ANDROID && !UNITY_EDITOR
            if (_failed) return;
            try
            {
                if (_vibrator == null)
                {
                    using (var player = new AndroidJavaClass("com.unity3d.player.UnityPlayer"))
                    using (var activity = player.GetStatic<AndroidJavaObject>("currentActivity"))
                        _vibrator = activity.Call<AndroidJavaObject>("getSystemService", "vibrator");
                }
                using (var effect = new AndroidJavaClass("android.os.VibrationEffect"))
                using (var oneShot = effect.CallStatic<AndroidJavaObject>("createOneShot", (long)milliseconds, -1))
                    _vibrator.Call("vibrate", oneShot);
            }
            catch (System.Exception e)
            {
                _failed = true;
                Debug.LogWarning($"Vibration unavailable: {e.Message}");
            }
#endif
        }
    }
}
